package discovery

import (
	"encoding/binary"
	"fmt"
	"io"
)

// ReliablePacket is sent by both server and client to deliver a message reliably.
// The receiver should respond with an AcknowledgementPacket containing the same identifiers.
// The sender may send it multiple times until it receives an acknowledgement from the remote network.
type ReliablePacket struct {
	// RecipientID is the network ID of the recipient.
	RecipientID uint64
	// Nonce is a random number generated by the sender.
	Nonce uint64
	// Sequence is a sequence number of this packet.
	Sequence uint64
	// SenderID is the network ID of the sender.
	SenderID uint64
	// Message is a MessagePacket containing the actual data used for signaling.
	Message *MessagePacket
}

// ID ...
func (*ReliablePacket) ID() uint16 {
	return IDReliablePacket
}

// Read ...
func (pk *ReliablePacket) Read(r io.Reader) error {
	if err := binary.Read(r, binary.LittleEndian, &pk.RecipientID); err != nil {
		return fmt.Errorf("read recipient ID: %w", err)
	}
	if err := binary.Read(r, binary.LittleEndian, &pk.Nonce); err != nil {
		return fmt.Errorf("read nonce: %w", err)
	}
	if err := binary.Read(r, binary.LittleEndian, &pk.Sequence); err != nil {
		return fmt.Errorf("read sequence: %w", err)
	}
	msg, senderID, err := unmarshal(r, IDMessagePacket)
	if err != nil {
		return fmt.Errorf("read encapsulated packet: %w", err)
	}
	pk.SenderID, pk.Message = senderID, msg.(*MessagePacket)
	return nil
}

// Write ...
func (pk *ReliablePacket) Write(w io.Writer) {
	if pk.Message == nil {
		// ...just in case. A nil message indicates a bug in Listener.
		// This is mostly safe because we don't allow users to send
		// direct packets.
		panic("discovery: ReliablePacket.Message is nil")
	}
	_ = binary.Write(w, binary.LittleEndian, pk.RecipientID)
	_ = binary.Write(w, binary.LittleEndian, pk.Nonce)
	_ = binary.Write(w, binary.LittleEndian, pk.Sequence)
	marshal(w, pk.Message, pk.SenderID)
}
